const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location - Sudd wetlands near Bor, South Sudan
  const bor = ee.Geometry.Point([31.56, 6.21]);
  const aoi = bor.buffer(20000); // 20km radius around Bor

  // 2. Define dates
  const date2019 = '2019-12-06';
  const date2021 = '2021-12-04';

  // 3. Load Sentinel-1 SAR data (cloud-independent)
  const s1_2019 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(aoi)
    .filterDate(date2019, ee.Date(date2019).advance(1, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const s1_2021 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(aoi)
    .filterDate(date2021, ee.Date(date2021).advance(1, 'day'))
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const size2019 = s1_2019.size().getInfo();
  const size2021 = s1_2021.size().getInfo();

  console.log(`2019 images: ${size2019}, 2021 images: ${size2021}`);

  // Check if data exists
  if (size2019 === 0 || size2021 === 0) {
    // Try wider date range
    const s1_2019_wide = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(aoi)
      .filterDate('2019-12-01', '2019-12-10')
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select('VV');

    const s1_2021_wide = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(aoi)
      .filterDate('2021-12-01', '2021-12-10')
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select('VV');

    const size2019_wide = s1_2019_wide.size().getInfo();
    const size2021_wide = s1_2021_wide.size().getInfo();

    console.log(`Wider range - 2019: ${size2019_wide}, 2021: ${size2021_wide}`);

    if (size2019_wide === 0 || size2021_wide === 0) {
      console.log('No data available for comparison');
      console.log('<answer>C1</answer>');
      return;
    }

    // Use closest images
    var img2019 = s1_2019_wide.sort('system:time_start').first();
    var img2021 = s1_2021_wide.sort('system:time_start').first();
  } else {
    var img2019 = s1_2019.first();
    var img2021 = s1_2021.first();
  }

  // 4. Detect water (VV < -15 dB is typically water)
  const water2019 = img2019.lt(-15);
  const water2021 = img2021.lt(-15);

  // 5. Calculate water extent area
  const stats2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2021 = water2021.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterPixels2019 = stats2019.get('VV').getInfo();
  const waterPixels2021 = stats2021.get('VV').getInfo();

  // Check pixel counts
  const count2019 = water2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('VV').getInfo();

  const count2021 = water2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('VV').getInfo();

  console.log(`2019: Water pixels=${waterPixels2019}, Total pixels=${count2019}`);
  console.log(`2021: Water pixels=${waterPixels2021}, Total pixels=${count2021}`);

  // 6. Validation
  if (count2019 === 0 || count2021 === 0) {
    console.log('No valid pixels after processing');
    console.log('<answer>C2</answer>');
    return;
  }

  if (waterPixels2019 === null || waterPixels2021 === null || 
      isNaN(waterPixels2019) || isNaN(waterPixels2021)) {
    console.log('Calculation failure');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Compare water extent
  const waterArea2019 = waterPixels2019 * 1e6 / 1e6; // km²
  const waterArea2021 = waterPixels2021 * 1e6 / 1e6; // km²

  console.log(`Water extent - 2019: ${waterArea2019.toFixed(2)} km², 2021: ${waterArea2021.toFixed(2)} km²`);

  if (waterArea2021 > waterArea2019) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
